from rest_framework_simplejwt.views import TokenRefreshSlidingView
from rest_framework_simplejwt.tokens import SlidingToken
from rest_framework.response import Response
from rest_framework import status
from .models import BillingAccount

class BillingAccountSlidingTokenRefreshView(TokenRefreshSlidingView):
    def post(self, request, *args, **kwargs):
        serializer = self.get_serializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        token = SlidingToken(request.data.get("token"))
        user_id = token.payload.get("user_id")
        new_billing_account = request.data.get("active_billing_account_id")

        if new_billing_account:
            if not BillingAccount.objects.filter(id=new_billing_account, authorized_users__id=user_id).exists():
                return Response({"detail": "Unauthorized billing account specified"}, status=status.HTTP_403_FORBIDDEN)
            token["active_billing_account_id"] = new_billing_account

        return Response({"token": str(token)}, status=status.HTTP_200_OK)
